import { fileURLToPath, URL } from 'node:url'
import { defineConfig } from 'vite'
import vue from '@vitejs/plugin-vue'

const fromRoot = (path: string) => fileURLToPath(new URL(path, import.meta.url))

// `@/config/env` is swapped per command, like Angular `fileReplacements`:
// the dev server and tests get env.development.ts, a production build gets the
// env.production.ts generated by scripts/set-env.mjs from $BACKEND_URL.
export default defineConfig(({ command }) => ({
  plugins: [vue()],
  resolve: {
    alias: [
      {
        find: /^@\/config\/env$/,
        replacement: fromRoot(command === 'build' ? './src/config/env.production.ts' : './src/config/env.development.ts'),
      },
      { find: '@', replacement: fromRoot('./src') },
    ],
  },
  server: {
    port: 4200,
    allowedHosts: ['frontend'],
    proxy: {
      '/api': {
        target: process.env.VITE_PROXY_TARGET || 'http://localhost:18080',
        changeOrigin: true,
        rewrite: (path) => path.replace(/^\/api/, ''),
      },
    },
  },
}))
